.ccf-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ccf-root,.ccf-root *,.ccf-root *::before,.ccf-root *::after{box-sizing:border-box}
.ccf-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ccf-root img{display:block;border:0;max-width:none}
.ccf-root > [data-node-id]{will-change:transform}
.ccf-root [hidden]{display:none!important}
.ccf-root [data-sh-theme="dark"]{display:none!important}
.ccf-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.ccf-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
